mapper.select:
SELECT COUNT(*)
FROM notice_item
WHERE title = #{title}

    AND notice_id != #{noticeId}

mapper.update:
UPDATE notice_item
SET title = #{title},
    description = #{description},
    icon_url = #{iconUrl}
WHERE notice_id = #{noticeId}

